import { z } from "zod";
import { ProductScope } from "./scope";
import { PriorityThresholds, ScoreWeights } from "./scoring";
import { ResearchApiSettings, DEFAULT_RESEARCH_APIS } from "./research";

/** "mock" returns canned, schema-valid output so the app runs offline and in tests. */
export const LlmProvider = z.enum(["anthropic", "mock"]);
export type LlmProvider = z.infer<typeof LlmProvider>;

export const ResearchProvider = z.enum(["firecrawl", "anthropic_web_search", "tavily", "off"]);
export type ResearchProvider = z.infer<typeof ResearchProvider>;

export const ThemePreference = z.enum(["system", "light", "dark"]);
export type ThemePreference = z.infer<typeof ThemePreference>;

/** Language of AI-written text (findings, requirements). The UI itself is English. */
export const OutputLanguage = z.enum(["en", "de"]);
export type OutputLanguage = z.infer<typeof OutputLanguage>;

export const MemberRole = z.enum(["owner", "editor", "viewer"]);
export type MemberRole = z.infer<typeof MemberRole>;

/** A teammate. "invited" until they join; sending invitations needs the sync backend. */
export const TeamMember = z.object({
  id: z.string().min(1),
  name: z.string().trim().min(1).max(80),
  email: z.email(),
  role: MemberRole,
  status: z.enum(["active", "invited"]),
});
export type TeamMember = z.infer<typeof TeamMember>;

/** Where shared workflows and decisions live: only this machine, a shared folder, or a Git repo. */
export const SharingMode = z.enum(["local", "shared_folder", "git"]);
export type SharingMode = z.infer<typeof SharingMode>;

/**
 * Everything the Settings page edits. API keys are NOT settings — they are stored encrypted in the
 * OS keychain by the main process (`settings.setSecret`); the UI only learns whether one is configured.
 */
export const Settings = z.object({
  app: z.object({
    theme: ThemePreference,
    snapToGrid: z.boolean(), // workplace
    showMinimap: z.boolean(), // workplace
    confirmBeforeDelete: z.boolean(),
  }),
  llm: z.object({
    provider: LlmProvider,
    model: z.string().min(1), // quality tier: clustering, derivation, challenge answers
    fastModel: z.string().min(1), // bulk tier: per-record signal extraction
    temperature: z.number().min(0).max(1),
    outputLanguage: OutputLanguage,
  }),
  research: z.object({
    provider: ResearchProvider,
    maxResultsPerQuery: z.number().int().min(1).max(50),
    allowedDomains: z.array(z.string()), // empty = any
    blockedDomains: z.array(z.string()),
    apis: ResearchApiSettings,
  }),
  scoring: z.object({
    weights: ScoreWeights,
    thresholds: PriorityThresholds,
  }),
  review: z.object({
    // The prototype has no login: this identity is the human actor in the audit trail.
    reviewer: z.object({
      userId: z.string().min(1),
      name: z.string().min(1),
      role: z.string().min(1),
    }),
  }),
  /** The global vehicle and market. Blocks set to "From Settings" use these. */
  defaultScope: ProductScope,
  collaboration: z.object({
    members: z
      .array(TeamMember)
      .refine(
        (ms) => new Set(ms.map((m) => m.email.toLowerCase())).size === ms.length,
        "This person is already on the team",
      ),
    sharing: SharingMode,
    sharedLocation: z.string().max(500), // folder path or Git URL; empty while sharing is "local"
    notifyOnReview: z.boolean(), // tell teammates when a HIL block waits for them
    requireSecondApproval: z.boolean(), // four-eyes rule for approving requirements
  }),
});
export type Settings = z.infer<typeof Settings>;

export const DEFAULT_SETTINGS: Settings = {
  app: {
    theme: "system",
    snapToGrid: true,
    showMinimap: false,
    confirmBeforeDelete: true,
  },
  llm: {
    provider: "mock",
    model: "claude-opus-5-5",
    fastModel: "claude-haiku-5-5",
    temperature: 0.2,
    outputLanguage: "en",
  },
  research: {
    provider: "off",
    maxResultsPerQuery: 8,
    allowedDomains: [],
    blockedDomains: [],
    apis: DEFAULT_RESEARCH_APIS,
  },
  scoring: {
    weights: {
      customer_impact: 3,
      evidence_strength: 2,
      competitive_gap: 2,
      trend_momentum: 2,
      brand_fit: 1,
      ease: 1,
    },
    thresholds: { must: 70, should: 50, could: 30 },
  },
  review: {
    reviewer: { userId: "pm-demo", name: "Demo PM", role: "Product Manager" },
  },
  defaultScope: {
    vehicleLine: "5 Series",
    derivative: "Sedan",
    vehicleCode: "5S",
    market: "EU",
    horizonYears: 5,
  },
  collaboration: {
    members: [],
    sharing: "local",
    sharedLocation: "",
    notifyOnReview: true,
    requireSecondApproval: false,
  },
};
import { z } from "zod";
import { Source, SourceKind, SourceRecord } from "./source";

export const RESEARCH_AGENT_IDS = [
  "reddit", "youtube", "instagram", "tiktok", "x", "owner_forums",
  "editorial_reviews", "competitor_models", "market_studies", "regional_context",
  "technology", "bmw_sales", "bmw_strategy",
] as const;
export const ResearchAgentId = z.enum(RESEARCH_AGENT_IDS);
export type ResearchAgentId = z.infer<typeof ResearchAgentId>;
export const RESEARCH_PROVIDER_IDS = [
  "firecrawl", "youtube", "apify", "x", "reddit", "openalex", "eurostat", "local_documents", "tavily",
] as const;
export const ResearchProviderId = z.enum(RESEARCH_PROVIDER_IDS);
export type ResearchProviderId = z.infer<typeof ResearchProviderId>;
export const APIFY_ACTORS = [
  "apify/instagram-scraper", "apify/instagram-comment-scraper",
  "clockworks/tiktok-scraper", "clockworks/tiktok-comments-scraper",
] as const;
export const ResearchProviderConfig = z.object({
  enabled: z.boolean().default(false),
  approval: z.enum(["not_granted", "granted"]).default("not_granted"),
  xSearchMode: z.enum(["recent", "full_archive"]).default("recent"),
  allowedActors: z.array(z.enum(APIFY_ACTORS)).default([]),
  redditUserAgent: z.string().min(10).max(200).default("ReqFlow/0.1 (approved research client)"),
}).strict();
export type ResearchProviderConfig = z.infer<typeof ResearchProviderConfig>;
export const DEFAULT_RESEARCH_APIS = Object.fromEntries(
  RESEARCH_PROVIDER_IDS.map((id) => [id, ResearchProviderConfig.parse({ enabled: id === "eurostat" || id === "local_documents" })]),
) as Record<ResearchProviderId, ResearchProviderConfig>;
export const ResearchApiSettings = z.object({
  firecrawl: ResearchProviderConfig.default(DEFAULT_RESEARCH_APIS.firecrawl),
  youtube: ResearchProviderConfig.default(DEFAULT_RESEARCH_APIS.youtube),
  apify: ResearchProviderConfig.default(DEFAULT_RESEARCH_APIS.apify),
  x: ResearchProviderConfig.default(DEFAULT_RESEARCH_APIS.x),
  reddit: ResearchProviderConfig.default(DEFAULT_RESEARCH_APIS.reddit),
  openalex: ResearchProviderConfig.default(DEFAULT_RESEARCH_APIS.openalex),
  eurostat: ResearchProviderConfig.default(DEFAULT_RESEARCH_APIS.eurostat),
  local_documents: ResearchProviderConfig.default(DEFAULT_RESEARCH_APIS.local_documents),
  tavily: ResearchProviderConfig.default(DEFAULT_RESEARCH_APIS.tavily),
}).strict().default(DEFAULT_RESEARCH_APIS);

export const ResearchLimits = z.object({
  maxResults: z.number().int().min(1).max(1000).default(50),
  maxRequests: z.number().int().min(1).max(1000).default(100),
  maxDocumentPages: z.number().int().min(1).max(500).default(20),
  timeoutMs: z.number().int().min(1000).max(900000).default(120000),
  concurrency: z.number().int().min(1).max(8).default(3),
  retries: z.number().int().min(0).max(3).default(2),
  cacheMaxAgeMs: z.number().int().min(0).max(86400000).default(0),
  maxProviderCredits: z.number().int().min(1).optional(),
  maxApifyChargeUsd: z.number().positive().max(100).default(1),
}).strict();
export type ResearchLimits = z.infer<typeof ResearchLimits>;
export const ResearchScope = z.object({
  brand: z.string().trim().min(1).default("BMW"),
  model: z.string().trim().min(1).default("5 Series"),
  currentGeneration: z.string().optional(), previousGeneration: z.string().optional(),
  derivative: z.string().optional(), propulsion: z.string().optional(), modelYear: z.string().optional(),
  markets: z.array(z.string().min(1)).default(["EU"]),
  languages: z.array(z.string().min(1)).default(["en", "de"]),
  publishedFrom: z.iso.date().optional(), publishedTo: z.iso.date().optional(),
  horizonYears: z.number().int().min(1).max(10).default(5),
  questions: z.array(z.string().trim().min(1)).default([]),
  keywords: z.array(z.string().trim().min(1)).default([]),
  competitors: z.array(z.object({ brand: z.string().min(1), model: z.string().min(1), generation: z.string().optional() }).strict()).default([]),
  allowedDomains: z.array(z.string()).default([]), blockedDomains: z.array(z.string()).default([]),
  urls: z.array(z.url()).default([]),
  documentIds: z.array(z.string().regex(/^file_[A-Za-z0-9_-]+$/)).default([]),
  eurostatDatasets: z.array(z.object({ id: z.string().regex(/^[a-zA-Z0-9_]+$/), filters: z.record(z.string(), z.string()).default({}) }).strict()).default([]),
}).strict().refine((s) => !s.publishedFrom || !s.publishedTo || s.publishedFrom <= s.publishedTo, "Publication start must precede end");
export type ResearchScope = z.infer<typeof ResearchScope>;
export const ResearchRequest = z.object({
  agents: z.array(ResearchAgentId).min(1).max(13), scope: ResearchScope,
  limits: ResearchLimits.default(() => ResearchLimits.parse({})),
}).strict();
export type ResearchRequest = z.infer<typeof ResearchRequest>;
export const RawRecordType = z.enum(["feedback", "passage", "transcript", "table", "product_description", "strategy_statement", "forecast", "metadata"]);
export const ExplicitAttribute = z.object({ value: z.string(), origin: z.enum(["source_explicit", "author_claim", "provider_metadata"]), locator: z.string().optional() });
export const RawTable = z.object({
  headers: z.array(z.string()), rows: z.array(z.array(z.union([z.string(), z.number(), z.boolean(), z.null()]))),
  units: z.array(z.string()).default([]), footnotes: z.array(z.string()).default([]),
  dimensions: z.record(z.string(), z.unknown()).optional(),
});
/** Provider-owned original content. No model-generated evidence or classifications. */
export const CollectedItem = z.object({
  provider: ResearchProviderId, sourceId: z.string().min(1), sourceUrl: z.url(), sourceTitle: z.string().min(1),
  sourceKind: SourceKind.default("other_web"), publisher: z.string().optional(),
  recordId: z.string().min(1), recordType: RawRecordType, text: z.string(),
  publishedAt: z.string().optional(), datePrecision: z.enum(["instant", "day", "month", "year", "unknown"]).default("unknown"),
