  locator: z.string().optional(), parentId: z.string().optional(), threadId: z.string().optional(),
  context: z.object({ id: z.string().optional(), url: z.string().optional(), text: z.string().optional() }).optional(),
  table: RawTable.optional(), metadata: z.record(z.string(), z.unknown()).default({}),
  limitations: z.array(z.string()).default([]),
}).strict();
