export const ResearchRecord = SourceRecord.extend({
  recordType: RawRecordType, originalSourceId: z.string(), originalRecordId: z.string(),
  provider: ResearchProviderId, originalUrl: z.url(),
  collectingAgents: z.array(ResearchAgentId), runIds: z.array(z.string()),
  retrievedAt: z.iso.datetime(), publishedAt: z.string().optional(),
  datePrecision: z.enum(["instant", "day", "month", "year", "unknown"]),
