export const AgentCollectionResult = z.object({
  agentId: ResearchAgentId, status: CollectionStatus, recordIds: z.array(z.string()),
  limitations: z.array(z.string()), requests: z.number().int().nonnegative(),
});
export type AgentCollectionResult = z.infer<typeof AgentCollectionResult>;
