export const ConnectionReport = z.object({
  state: ConnectionState, message: z.string(), testedAt: z.iso.datetime().optional(),
  capabilities: z.array(z.string()).default([]), limitations: z.array(z.string()).default([]),
});
export type ConnectionReport = z.infer<typeof ConnectionReport>;
export const ResearchProviderStatus = z.object({
  id: ResearchProviderId, config: ResearchProviderConfig,
  credentialsConfigured: z.record(z.string(), z.boolean()), connection: ConnectionReport,
});
export type ResearchProviderStatus = z.infer<typeof ResearchProviderStatus>;
export const ResearchAgentDefinition = z.object({
  id: ResearchAgentId, label: z.string(), description: z.string(), providers: z.array(ResearchProviderId),
});
export type ResearchAgentDefinition = z.infer<typeof ResearchAgentDefinition>;
